'use strict';
const $=s=>document.querySelector(s);
const labels={official_website:'Official website',business_description:'Business description',financials:'Annual accounts',financial_history:'Available filing years',leadership:'Current registered roles',workplaces:'Registered workplaces',hiring:'Hiring information',public_activity:'Public activity',public_reputation:'Public reviews and ratings',company_owned_profiles:'Company profiles',registry_activity:'Registered activity',registered_purpose:'Registered legal purpose',historical_names:'Registered name history',legal_status:'Registry legal status',legal_name:'Legal name',legal_form:'Legal form',registered_address:'Registered address',registered_postal_address:'Registered postal contact',industry:'Industry',registered_employee_count:'Registered employees',registered_website:'Registry website',latest_submitted_accounts:'Latest filed accounts',group_structure:'Group structure',locations:'Locations',revenue:'Operating revenue',operating_result:'Operating result',profit_before_tax:'Profit before tax',annual_result:'Annual result',assets:'Assets',equity:'Equity',liabilities:'Liabilities',portfolio_result:'Fund portfolio result',management_result:'Fund management result'};
const state={runs:[],run:null,data:null,page:'overview',query:'',status:'all',tablePage:0,sort:'name',company:null,companyTab:'profile',detail:null,scope:'company',recordId:null,evidenceId:null,config:null,signature:null,loading:false,userSelectedRun:false,compare:[],compareProfiles:[],compareScope:'company'};
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=value=>escape(value??'—');
const fieldLabel=field=>labels[field]??field.replace(/^group_/,'Group ').replaceAll('_',' ');
const number=value=>new Intl.NumberFormat('en-GB').format(value);
const usd=value=>'$'+Number(value??0).toFixed(3);
const pct=(n,d)=>d?Math.round(n/d*100):0;
const duration=ms=>ms<1000?Math.round(ms)+' ms':ms<60000?(ms/1000).toFixed(1)+' s':Math.floor(ms/60000)+'m '+Math.round(ms%60000/1000)+'s';
const time=value=>value?new Date(value).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
const date=value=>value?new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
function money(amount,currency){if(amount===null||amount===undefined)return 'Not reported';return `${currency??'Unspecified currency'} ${new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(amount)}`;}
function badge(status){const names={completed:'Complete',partial:'Partial coverage',failed:'Failed',running:'Researching',queued:'Queued',finished:'Finished',available:'Supported',not_available:'Not reported',blocked:'Blocked',not_applicable:'Not applicable',ambiguous:'Needs review'};const color=['completed','finished','available'].includes(status)?'green':['partial','ambiguous'].includes(status)?'orange':status==='failed'?'red':['running','queued'].includes(status)?'blue':'';return `<span class="badge ${color}">${text(names[status]??status)}</span>`;}
async function api(path,options){const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw Error(data.error??'Request failed');return data;}
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,3500);}
function displayError(message){$('#errorBanner').textContent=message;$('#errorBanner').hidden=!(message);}
function activeRun(){return ['running','queued'].includes(state.data?.run.status);}
function updateRuns(){const select=$('#runSelect'),signature=JSON.stringify(state.runs.map(r=>r.run_id));if(select.dataset.signature!==signature){select.innerHTML=state.runs.map(r=>`<option value="${text(r.run_id)}">${text(r.run_id.replaceAll('_',' '))}</option>`).join('')||'<option>No research runs yet</option>';select.dataset.signature=signature;}if(state.run)select.value=state.run;}
async function refresh(force=false){
 if(state.loading)return;state.loading=true;
 try{
  state.runs=await api('/api/runs');
  if(!state.run||!state.runs.some(r=>r.run_id===state.run)||(!state.userSelectedRun&&state.runs.some(r=>['running','queued'].includes(r.status)&&r.run_id!==state.run))){state.run=state.runs.find(r=>['running','queued'].includes(r.status))?.run_id??state.runs[0]?.run_id??null;}
  updateRuns();
  if(!state.run){$('#content').innerHTML='<div class="panel empty"><h2>Your next company story starts here.</h2><p>Start a research run to bring registry facts, reported financials, and web evidence into one workspace.</p><button class="primary" data-action="new-run">Start your first run →</button></div>';return;}
  const requestedRun=state.run,data=await api('/api/runs/'+encodeURIComponent(requestedRun)),signature=JSON.stringify(data);if(state.run!==requestedRun){setTimeout(()=>refresh(true),0);return;}
  state.data=data;
  if(force||signature!==state.signature){state.signature=signature;render();}
  $('#connectionLabel').textContent=activeRun()?'Live updates · every 2s':'Workspace up to date';$('#connectionDot').style.background='#36a57b';$('#updatedLabel').textContent='Updated '+time(new Date());displayError('');
 }catch(error){displayError('Could not refresh this workspace: '+error.message);$('#connectionLabel').textContent='Connection interrupted';$('#connectionDot').style.background='#d58d67';}
 finally{state.loading=false;}
}
function render(){
 const d=state.data;if(!d)return;
 const titles={overview:'A clearer picture of every company.',companies:'Explore the companies behind the numbers.',financials:'Reported financials, without the guesswork.',sources:'Coverage you can actually inspect.',activity:'See the research as it happens.'};
 $('#pageTitle').textContent=titles[state.page];$('#pageCrumb').textContent=state.page==='sources'?'Source coverage':state.page[0].toUpperCase()+state.page.slice(1);
 $('#pageSubtitle').textContent=state.page==='financials'?'Company and group statements stay separate. Every number keeps its period and currency.':state.page==='activity'?'A live record of registry requests, source research, and saved company profiles.':'Registry facts, financials, and web evidence. All in one place.';
 $('#runBadge').outerHTML=badge(d.run.mode==='demo'?'Offline demo':d.run.status).replace('<span ','<span id="runBadge" ');
 $('#navCount').textContent=d.companies.length;$('#exportButton').href=`/api/runs/${encodeURIComponent(state.run)}/export`;
 document.querySelectorAll('[data-page]').forEach(button=>{button.classList.toggle('active',button.dataset.page===state.page);button.setAttribute('aria-current',button.dataset.page===state.page?'page':'false');});
 const focused=document.activeElement?.id,selection=focused==='companySearch'?$('#companySearch').selectionStart:null;
 const total=d.companies.length,coverage=d.coverage.reduce((n,f)=>n+f.available,0),possible=d.coverage.reduce((n,f)=>n+f.total,0),financial=d.coverage.find(c=>c.field==='financials')?.available??0;
 let html=d.run.review_only?'<div class="banner info">Recorded live benchmark · captured 15 October 2026. Review the saved facts, excerpts and hashes offline. Full raw-source caches are not distributed.</div>':d.run.mode==='demo'?'<div class="banner info">Offline demo · these companies and research facts are fictional. No live sources or paid API calls were used.</div>':'';
 if(d.run.report?.bounded_semantic_review?.complete)html+=`<div class="banner info"><strong>Assisted source audit complete for ${number(d.run.report.bounded_semantic_review.companies)} companies.</strong> Compared with ${number(d.run.report.bounded_semantic_review.reference_facts)} permitted reference facts. This is repaired development data; full-web recall, a blind human-calibrated accuracy rate and the official challenge score remain unestablished.</div>`;
 else if(d.run.report?.semantic_validation_complete===false||d.run.semantic_repair?.offline)html+=`<div class="banner error"><strong>Provisional diagnostic — semantic verification incomplete.</strong> Saved-source policy repairs are available for inspection. New extraction and semantic model checks were not completed; these profiles do not establish challenge accuracy or recall.</div>`;
 if(d.run.report?.reviewed_filing_recovery)html+=`<div class="banner info">${number(d.run.report.reviewed_filing_recovery.companies_repaired)} original filings recovered after failed normalized responses. Selected tables were visually reviewed; comparative year columns keep unknown full dates. This is assisted source repair, with later observations for those companies.</div>`;
 if(d.run.report?.publication_recheck)html+=`<div class="banner info">Publication rules rechecked across ${number(d.run.report.publication_recheck.companies)} companies in ${duration(d.run.report.publication_recheck.elapsed_ms)}, after ${duration(d.run.report.publication_recheck.database_copy_and_integrity_ms)} of database preparation. ${number(d.run.report.publication_recheck.physical_requests)} new public requests and ${number(d.run.report.publication_recheck.model_calls)} model calls. ${d.run.report?.bounded_semantic_review?.complete?'Bounded source-context comparison is recorded separately.':'Semantic verification remains incomplete.'}</div>`;
 if(d.run.report?.semantic_repair)html+=`<div class="banner info">This repair processed ${number(d.run.report.semantic_repair.companies)} companies in ${duration(d.run.report.semantic_repair.elapsed_ms)}. ${number(d.run.report.semantic_repair.physical_requests)} new public requests and ${number(d.run.report.semantic_repair.new_model_receipts)} new model receipts. Original acquisition timing and incomplete usage remain separate.</div>`;
 if(d.run.processing_replay)html+=`<div class="banner info">Saved sources rechecked. ${d.run.processing_replay.network_calls||d.run.processing_replay.model_calls?number(d.run.processing_replay.network_calls??0)+' public requests and '+number(d.run.processing_replay.model_calls??0)+' additional model calls recorded.':'No new source or model calls.'} Collection times are from the original run; recorded usage includes processing. This recheck took ${duration(d.run.processing_replay.elapsed_ms)}.</div>`;
 if(activeRun())html+=`<div class="progress-banner"><span class="spinner"></span><strong>${d.run.shared_sources?.nav?.status==='running'?'Preparing shared sources':'Research in progress'}</strong><span>${d.companies.filter(c=>c.status==='running').length} active · ${d.companies.filter(c=>c.status==='queued').length} queued</span><div class="mini-progress"><span style="width:${pct(d.completed,total)}%"></span></div><small>${d.completed} of ${total} saved</small></div>`;
 html+=`<section class="metrics-grid" aria-label="Run metrics"><div class="metric"><div class="metric-label">Companies researched <span>▤</span></div><div class="metric-number">${d.completed}<small> / ${total}</small></div><div class="mini-progress"><span style="width:${pct(d.completed,total)}%"></span></div></div><div class="metric"><div class="metric-label">Populated fields <span>◈</span></div><div class="metric-number">${pct(coverage,possible)}<small>%</small></div><div class="metric-foot"><b>${coverage} populated</b> of ${possible} tracked fields</div></div><div class="metric"><div class="metric-label">Financial statements <span>▥</span></div><div class="metric-number">${d.financial_records}</div><div class="metric-foot">Across <b>${financial} companies</b> · retained statements and comparative columns</div></div><div class="metric"><div class="metric-label">${d.run.report?.keyless?'External API charges':'Exa usage'} <span>↗</span></div><div class="metric-number">${d.run.exa_transport==='connector'||d.run.report?.exa_transport==='connector'?'—':usd(d.operations.cost)}</div><div class="metric-foot">${d.run.exa_transport==='connector'||d.run.report?.exa_transport==='connector'?'Charges not reported · ':''}${d.operations.shared_nav_requests?number(d.operations.company_source_requests)+' company + '+number(d.operations.shared_nav_requests)+' shared NAV requests':number(d.operations.requests)+' source requests'} · ${d.run.mode==='eve'?(d.run.model_provider==='chatgpt'||String(d.run.report?.model_billing??'').includes('subscription')?'local model subscription':'model billed separately'):'no model billing'}</div></div></section>`;
 if(d.run.report?.model_api_equivalent_usd!==undefined)html+=`<div class="banner info">Model API equivalent: ${d.run.report.model_api_equivalent_usd===null?'Unknown (usage incomplete)':usd(d.run.report.model_api_equivalent_usd)} · Recorded usage: ${number(d.run.report.model_input_tokens??0)} input / ${number(d.run.report.model_output_tokens??0)} output tokens · batch ${duration(d.run.report.elapsed_ms??0)} · company p95 ${duration(d.run.report.company_runtime_ms?.p95??0)}. Subscription fees and unknown source bills are separate.</div>`;
 if(d.run.report?.keyless)html+=`<div class="banner info">Native search API equivalent: ${d.run.report.search_api_equivalent_usd===null?'Unknown (incomplete receipt)':usd(d.run.report.search_api_equivalent_usd??0)} · combined with model tokens: ${d.run.report.combined_api_equivalent_usd==null?'Unknown':usd(d.run.report.combined_api_equivalent_usd??0)}. Existing subscription capacity is used; these are API price equivalents.</div>`;
 if(d.run.report?.shared_sources?.nav?.mode==='frozen-keyless')html+=`<div class="banner info">NAV snapshot cutoff: ${text(d.run.report.nav_source?.completed_at??'Unknown')}. Frozen public source; no live NAV sweep was performed.</div>`;
 if(['overview','sources'].includes(state.page)&&d.run.report?.hiring_observations){const h=d.run.report.hiring_observations;html+=`<div class="banner info">NAV checked for ${number(h.companies_with_verified_nav_query)} companies: ${number(h.attributed_nav_ads)} attributed active ads. ${number(h.companies_with_other_recruitment_information)} ${h.companies_with_other_recruitment_information===1?'company has':'companies have'} other recruitment information. NAV excludes Finn ads; a zero here does not mean a company is not hiring elsewhere.</div>`;}
 if(d.run.shared_sources?.nav?.status==='failed')html+=`<div class="banner info">NAV source check could not finish: ${text(d.run.shared_sources.nav.error)}. Other company research continues; no hiring absence is inferred.</div>`;
 if(state.page==='overview'&&d.companies.some(c=>c.status==='partial'))html+=`<div class="banner info">${d.companies.filter(c=>c.status==='partial').length} profiles have unresolved fields. “Partial coverage” means some requested evidence is still unknown; supported facts remain available. Use the evidence filter below to find hiring or company profiles.</div>`;
 if(state.page==='overview')html+=`<section class="overview-grid"><div class="panel"><div class="panel-heading"><div><h3>Coverage at a glance</h3><p>Populated facts across ${total} companies · source checks counted separately</p></div><button class="quiet" data-page="sources">View all ↗</button></div><div class="coverage">${coverageRows(d.coverage)}</div></div><div class="panel"><div class="panel-heading"><div><h3>Latest activity</h3><p>Behind every result, a recorded step</p></div><button class="quiet" data-page="activity">↗</button></div>${activity(d.events.slice(0,5))}</div></section>`;
 if(['overview','companies','financials'].includes(state.page))html+=companyTable(state.page==='financials');
 if(state.page==='sources')html+=`<section class="panel"><div class="panel-heading"><div><h3>Evidence coverage by field</h3><p>A field counts only when it has an available value. Unresolved fields stay visible.</p></div><span class="badge">${d.coverage.length} tracked fields</span></div><div class="source-table">${coverageRows(d.coverage,true)}</div></section><div class="banner info">Coverage measures availability, not factual precision. Inspect individual evidence for context, entity scope, and freshness.</div>`;
 if(state.page==='activity')html+=`<section class="panel long-activity"><div class="panel-heading"><div><h3>Run activity</h3><p>Latest ${d.events.length} recorded steps · newest first</p></div><span class="badge">${d.error_count} recorded issues</span></div>${activity(d.events)}</section>`;
 $('#content').innerHTML=html;
 if(focused==='companySearch'&&$('#companySearch')){$('#companySearch').focus({preventScroll:true});$('#companySearch').setSelectionRange(selection,selection);}
}
function coverageRows(rows,full=false){return rows.map(row=>`<div class="coverage-row"><span>${text(fieldLabel(row.field))}</span><div class="bar-track" role="meter" aria-label="${text(fieldLabel(row.field))} available" aria-valuenow="${row.available}" aria-valuemin="0" aria-valuemax="${row.total}"><div class="bar-fill" style="width:${pct(row.available,row.total)}%"></div></div><span>${full?`${row.available} / ${row.total}`:pct(row.available,row.total)+'%'}</span></div>`).join('');}
function activity(events){return `<div class="activity-list">${events.length?events.map(event=>`<div class="activity-item"><span class="activity-icon">${event.stage==='finished'?'✓':event.stage==='research'?'◈':event.stage==='run'?'◫':'↗'}</span><div><p>${text(event.message)}</p><small>${time(event.at)}${event.org?' · '+text(event.org):''}</small></div></div>`).join(''):'<div class="empty">This saved run has no activity history.</div>'}</div>`;}
function filteredCompanies(financial){let rows=state.data.companies.filter(c=>(state.status==='all'||c.status===state.status)&&(!state.coverageField||state.coverageField==='all'||(state.coverageField==='hiring_signal'?c.has_hiring_signal:state.coverageField==='hiring_checked'?c.has_hiring_check:c.available_fields?.includes(state.coverageField)))&&(String(c.name)+' '+c.organisation_number).toLowerCase().includes(state.query.toLowerCase()));if(financial)rows=rows.filter(c=>c.has_financials);rows.sort((a,b)=>state.sort==='coverage'?b.available-a.available:state.sort==='cost'?b.cost-a.cost:String(a.name).localeCompare(String(b.name),'nb'));return rows;}
function companyTable(financial=false){const rows=filteredCompanies(financial),pageSize=state.page==='overview'?8:15;state.tablePage=Math.min(state.tablePage,Math.max(0,Math.ceil(rows.length/pageSize)-1));const start=state.tablePage*pageSize,visible=rows.slice(start,start+pageSize);return `<section class="panel"><div class="panel-heading"><div><h3>${financial?'Companies with reported financials':'Company research'}</h3><p>${financial?'Inspect periods, currencies, statement scope, and original evidence.':'Open a company to see the facts and the evidence behind them.'}</p></div><div class="compare-tools"><button class="secondary" data-action="compare" ${state.compare.length<2?'disabled':''}>Compare${state.compare.length?' ('+state.compare.length+')':''}</button><span class="badge">${rows.length} ${rows.length===1?'company':'companies'}</span></div></div><div class="table-controls"><div class="search-wrap"><span>⌕</span><input id="companySearch" type="search" placeholder="Search company or number…" aria-label="Search company or organisation number" value="${text(state.query)}"></div><div><select id="statusFilter" aria-label="Filter by research status"><option value="all">All statuses</option><option value="completed" ${state.status==='completed'?'selected':''}>Complete</option><option value="partial" ${state.status==='partial'?'selected':''}>Partial coverage</option><option value="running" ${state.status==='running'?'selected':''}>Researching</option><option value="queued" ${state.status==='queued'?'selected':''}>Queued</option><option value="failed" ${state.status==='failed'?'selected':''}>Failed</option></select> <select id="coverageFilter" aria-label="Filter by supported field"><option value="all">All evidence</option><option value="hiring_checked" ${state.coverageField==='hiring_checked'?'selected':''}>Hiring sources checked</option><option value="hiring_signal" ${state.coverageField==='hiring_signal'?'selected':''}>Vacancies / careers</option><option value="company_owned_profiles" ${state.coverageField==='company_owned_profiles'?'selected':''}>Has company profiles</option><option value="official_website" ${state.coverageField==='official_website'?'selected':''}>Has official website</option></select> <select id="sortCompanies" aria-label="Sort companies"><option value="name">Name A–Z</option><option value="coverage" ${state.sort==='coverage'?'selected':''}>Most coverage</option><option value="cost" ${state.sort==='cost'?'selected':''}>Highest cost</option></select></div></div><div class="table-wrapper"><table><thead><tr><th scope="col"><span class="sr-only">Select to compare</span></th><th scope="col">Company</th><th scope="col">Research status</th><th scope="col">Supported fields</th><th scope="col">${financial?'Latest period':'Financials'}</th><th scope="col">${state.data?.run?.report?.keyless?'External API charge':'Exa cost'}</th><th scope="col"><span class="sr-only">Inspect</span></th></tr></thead><tbody>${visible.map(c=>`<tr><td class="checkbox-cell"><input type="checkbox" data-compare="${text(c.organisation_number)}" aria-label="Compare ${text(c.name)}" ${state.compare.includes(c.organisation_number)?'checked':''} ${['queued','running'].includes(c.status)?'disabled':''}></td><td><div class="company-cell"><span class="company-mark">${text(String(c.name).split(/\s+/).slice(0,2).map(s=>s[0]).join(''))}</span><div><strong>${text(c.name)}</strong><small>${text(c.organisation_number)}</small></div></div></td><td>${badge(c.status)}</td><td><span class="coverage-number">${c.available} <span class="muted">/ ${c.total}</span><i><span style="width:${pct(c.available,c.total)}%"></span></i></span></td><td>${c.has_financials?`<span class="badge green">${text(c.financial_year?.slice(0,4)??'Available')}</span>`:'<span class="muted">—</span>'}</td><td>${state.data.run.exa_transport==='connector'||state.data.run.report?.exa_transport==='connector'?'Unreported':usd(c.cost)}</td><td><button class="inspect" data-company="${text(c.organisation_number)}" aria-label="Inspect ${text(c.name)}">↗</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No companies match these filters.</div></td></tr>'}</tbody></table></div><div class="table-foot"><span>${rows.length?start+1:0}–${Math.min(start+pageSize,rows.length)} of ${rows.length} ${rows.length===1?'company':'companies'}</span><div class="pagination"><button data-action="prev-page" ${start===0?'disabled':''} aria-label="Previous page">←</button><button data-action="next-page" ${start+pageSize>=rows.length?'disabled':''} aria-label="Next page">→</button></div></div></section>`;}
async function openCompany(org){state.userSelectedRun=true;state.company=org;state.companyTab=state.page==='financials'?'financials':'profile';state.evidenceId=null;state.recordId=null;state.scope='company';$('#companyPanel').innerHTML='<div class="loading"><span class="spinner"></span> Opening company evidence…</div>';if(!$('#companyDialog').open)$('#companyDialog').showModal();try{const detail=await api(`/api/runs/${encodeURIComponent(state.run)}/companies/${org}`);if(state.company!==org)return;state.detail=detail;renderCompany();}catch(error){$('#companyPanel').innerHTML=`<div class="company-body"><div class="dialog-heading"><h2 id="companyTitle">Company not ready</h2><button class="icon-button" data-close="companyDialog" aria-label="Close company">×</button></div><p class="muted">${text(error.message)}</p></div>`;}}
function renderCompany(){const {profile:p,job,calls,events}=state.detail,company=state.data.companies.find(c=>c.organisation_number===state.company),name=p?.claims.find(c=>c.field==='legal_name')?.value??company?.name??state.company;$('#companyPanel').innerHTML=`<div class="company-header"><div class="company-header-top"><span class="company-mark">${text(String(name).split(/\s+/).slice(0,2).map(s=>s[0]).join(''))}</span><div><div class="eyebrow">COMPANY INTELLIGENCE</div><h2 id="companyTitle">${text(name)}</h2><div class="company-meta"><span>Org. ${text(state.company)}</span>${badge(p?.run.terminal_status??'running')}<span>${p?duration(p.operations.runtime_ms):'In progress'}</span></div></div><button class="icon-button" data-close="companyDialog" aria-label="Close company details">×</button></div><div class="company-tabs" role="tablist" aria-label="Company details">${['profile','financials','evidence','changes','errors'].map(tab=>`<button role="tab" aria-selected="${state.companyTab===tab}" class="${state.companyTab===tab?'active':''}" data-company-tab="${tab}">${tab[0].toUpperCase()+tab.slice(1)}${tab==='errors'&&p?.errors.length?' · '+p.errors.length:''}</button>`).join('')}</div></div><div class="company-body" role="tabpanel">${!p?`<div class="banner info">Research is still in progress. Close and reopen this company to see its latest saved result.</div>${activity(events)}`:state.companyTab==='profile'?profileView(p):state.companyTab==='financials'?financialView(p):state.companyTab==='evidence'?evidenceView(p):state.companyTab==='changes'?changesView(p):errorsView(p,calls)}</div>`;}
function valueView(value){if(value===null||value===undefined)return '—';if(typeof value==='object'){if(value.kind==='parent_survey')return nurserySurveyView(value);if('amount'in value)return text(money(value.amount,value.currency));
if('beskrivelse'in value&&'kode'in value)return text(value.beskrivelse)+' <span class="muted">('+text(value.kode)+')</span>';
if('adresse'in value||'poststed'in value)return text([...(Array.isArray(value.adresse)?value.adresse:[]),[value.postnummer,value.poststed].filter(Boolean).join(' '),value.land].filter(Boolean).join(', '));
if(Array.isArray(value.roles))return `<div class="table-wrapper"><table><thead><tr><th>Name</th><th>Registered role</th><th>Registry group updated</th></tr></thead><tbody>${value.roles.map(role=>`<tr><td>${text(Array.isArray(role.name)?role.name.join(' '):role.name)}</td><td>${text(role.role??role.role_code)}</td><td>${text(role.last_changed)}${role.entity_approval_status?'<br>'+text(role.entity_approval_status):''}</td></tr>`).join('')||'<tr><td colspan="3">No current registered roles returned.</td></tr>'}</tbody></table></div>${value.inactive_registered_relations?.length?`<details class="audit-meta"><summary>${value.inactive_registered_relations.length} inactive register relation(s) preserved</summary>${value.inactive_registered_relations.map(role=>`<p>${text(Array.isArray(role.name)?role.name.join(' '):role.name)} · ${text(role.role??role.role_code)} · ${role.person_deceased?'deceased person':role.entity_deleted?'deleted entity':'status unresolved'}</p>`).join('')}</details>`:''}<p class="audit-meta">Registry relations do not prove current operational leadership. Update dates belong to the role group, not the appointment.</p>`;
if(Array.isArray(value.locations))return `<div class="muted">${value.locations.length} registered workplaces${value.complete===false?' · additional pages not collected':''}</div><details><summary class="evidence-link">View workplace addresses</summary>${value.locations.map(place=>`<div class="workplace"><strong>${text(place.name)}</strong><div><small class="muted">${place.address_scope==='registered_subunit_postal_contact'?'Registered postal contact':'Registered location'}</small>${place.address?valueView(place.address):'Address not reported'}</div>${place.postal_address&&place.address_scope!=='registered_subunit_postal_contact'?`<div><small class="muted">Registered postal contact · physical operating use is not established</small>${valueView(place.postal_address)}</div>`:''}<small class="muted">${text(place.organisation_number)} · ${place.employees===null?'Employee count not reported':number(place.employees)+' registered employees'}</small></div>`).join('')}</details>`;
return `<pre>${text(JSON.stringify(value,null,2))}</pre>`;}if(typeof value==='string'&&/^https:\/\//.test(value))return `<a class="source-url" href="${text(value)}" target="_blank" rel="noreferrer">${text(value)} ↗</a>`;return text(value);}
function nurserySurveyView(v){const count=x=>x===null||x===undefined?'not reported':number(x);return `<p><strong>${text(v.survey_year)} parent survey</strong> · ${text(v.nursery_name)}<br><span class="muted">Registered nursery unit ${text(v.subunit_organisation_number)} · scale ${text(v.scale_min)}–${text(v.scale_max)}</span></p><div class="table-wrapper"><table><thead><tr><th>Survey dimension</th><th>Reported score</th></tr></thead><tbody>${v.metrics.map(m=>`<tr><td>${text(m.label)}</td><td>${m.value===null?'Not reported or suppressed':text(m.value)+' / '+text(v.scale_max)}</td></tr>`).join('')}</tbody></table></div><p class="audit-meta">Responses: ${count(v.respondent_count)} of ${count(v.invited_count)} invited · response rate ${v.response_percent===null?'not reported':text(v.response_percent)+'%'}. Nursery survey results describe respondents in the stated year. They are not a company-wide sentiment score or a ranking.</p><p class="audit-meta">${text(v.attribution)}. Source fields selected and labelled; numbers unchanged. <a href="https://www.udir.no/om-udir/data/vilkar-for-bruk/" target="_blank" rel="noreferrer">Data terms</a> · <a href="https://data.norge.no/nlod/no/2.0" target="_blank" rel="noreferrer">NLOD licence</a></p>`;}
function hiringValueView(value){
 if(value&&typeof value==='object'&&typeof value.active_ads_attributed==='number')return `<div><strong>${number(value.active_ads_attributed)} active NAV ad${value.active_ads_attributed===1?'':'s'} attributed as of ${text(value.observed_at)}</strong><p class="financial-explainer">Exact employer or registered-subunit organisation numbers checked. ${text(value.scope)}. This does not establish whether the company is hiring elsewhere.</p>${value.advertisements?.map(ad=>`<p><a class="source-url" href="${text(ad.url)}" target="_blank" rel="noreferrer">${text(ad.title)} ↗</a><br><small>${text(ad.employer)} · org. ${text(ad.employer_org)} · published ${date(ad.published_at)} · expires ${date(ad.expires_at)}</small></p>`).join('')??''}<details><summary class="evidence-link">Collection scope and limits</summary><p>Collected ${date(value.observed_from)}–${date(value.observed_at)}. ${number(value.unresolved_employer_records)} active NAV records lacked usable employer identifiers and could not be attributed. ${value.advertisements_complete?'All attributed ad links are listed.':'The count includes all attributed ads; the first four links are shown.'}</p></details></div>`;

 const raw=String(value),cut=raw.search(/\n## (Om |About )/i),preview=(cut>0?raw.slice(0,cut):raw.slice(0,650)).trim().replace(/^#{1,6}\s+/gm,'').replace(/\n{2,}/g,'\n');
 const urls=[...new Set(raw.match(/https:\/\/[^\s<>"\]\)]+/g)??[])].filter(url=>/\/(jobs|stillinger|job)\//i.test(url)).slice(0,6);
 return `<div>${text(preview)}</div>${urls.length?`<div class="financial-controls">${urls.map((url,i)=>`<a class="secondary" href="${text(url)}" target="_blank" rel="noreferrer">Recruitment page ${i+1} ↗</a>`).join('')}</div>`:''}${preview!==raw.trim()?`<details><summary class="evidence-link">Full supported excerpt</summary><pre class="source-content">${text(raw)}</pre></details>`:''}`;
}
function synthesisView(p){const summary=p.synthesis;if(!summary)return '';return `<article class="claim-card"><h3>Company brief</h3>${summary.sections.map(section=>`<p><strong>${text(section.title)}</strong><br>${text(section.text)} ${section.evidence_ids.length?`<button class="evidence-link" data-evidence="${text(section.evidence_ids[0])}">Inspect evidence →</button>`:''}</p>`).join('')}<p class="audit-meta">Unknown: ${summary.unknown_fields.map(fieldLabel).map(text).join(', ')||'None recorded'}. ${text(summary.note)}</p></article>`;}
function locationScopeView(c){if(c.field!=='locations')return'';const labels={reported_contact:'Published company contact; current use as a staffed operating office is not established.',seller_contact:'Published seller contact; a shop, staffed office or workshop is not established.',property_portfolio:'Property in a reported portfolio; this does not establish a company operating office.',area_description:'Reported geographic area; a company operating site is not established.',housing_property_area:'Location of the named housing cooperative; a company operating office is not established.',care_of_address:'Care-of contact address; a staffed company office is not established.',event_venue:'Venue for the reported event; a company operating office is not established.',service_area:'Service territory; this is not evidence of a company office in the area.',secondary_contact:'Source-reported contact address; a shop, staffed office or workshop is not established.',historical_document_contact:'Contact address in a historical document; current use is not established.',reported_company_base:'Company-reported geographic base; a staffed office or factory is not established.',postal_contact:'Postal contact address; a physical operating location is not established.',company_reported_laboratory:'Company-reported laboratory location.',company_reported_workshop:'Company-reported operating workshop; no independent site visit was performed.',company_reported_production_plant:'Company-reported production premises; location and floor area were not independently inspected or measured.'};return labels[c.qualifiers?.location_kind]?`<p class="audit-meta">${text(labels[c.qualifiers.location_kind])}</p>`:'';}
function profileView(p){const main=['business_description','registry_activity','registered_purpose','historical_names','legal_status','official_website','registered_website','industry','registered_address','registered_postal_address','registered_employee_count','hiring','locations','public_activity','public_reputation','company_owned_profiles','leadership','workplaces'];return synthesisView(p)+main.flatMap(field=>p.claims.filter(c=>c.field===field)).map(c=>`<article class="claim-card"><div class="claim-top"><strong>${text(c.qualifiers?.attribution==='nav-complete-index-exact-org'?'NAV source check':c.qualifiers?.source_scope==='official_reported_competence'?'Approved competence':fieldLabel(c.field))}</strong>${badge(c.availability==='failed'?'Unresolved':c.availability)}</div><div class="claim-value">${c.availability==='available'?(c.field==='hiring'?hiringValueView(c.value):valueView(c.value)):`<span class="muted">${c.availability==='not_available'?'Not reported in the checked source.':c.availability==='ambiguous'?text(c.qualifiers?.reason??'The available evidence does not establish an exact match.'):'No supported value was published for this field.'}</span>`}</div>${typeof c.qualifiers?.scope_note==='string'?`<p class="audit-meta">${text(c.qualifiers.scope_note)}</p>`:''}${c.qualifiers?.source_scope==='official_reported_competence'?`<p class="audit-meta">Official approval: ${text(c.qualifiers.approval_valid_from??'start unknown')}–${text(c.qualifiers.approval_valid_until??'end unknown')}. Competence scope only; completed projects and current service delivery are not established.</p>`:''}${c.qualifiers?.comparative_ranking_independently_established===false?'<p class="audit-meta">Company self-description; independent comparative ranking is not established.</p>':''}${c.qualifiers?.brand_history_not_legal_entity_formation===true?`<p class="audit-meta">Publisher-reported brand/predecessor history. This legal entity formed in ${text(c.qualifiers.legal_entity_formation_year)}; continuous legal-entity operation from the earlier date is not established.</p>`:''}${c.qualifiers?.current_certification_independently_verified===false?'<p class="audit-meta">Publisher-reported credentials; independent current certificate status, scope and validity are not established.</p>':''}${c.qualifiers?.source_internal_recruitment_conflict===true?'<p class="audit-meta">The saved source has conflicting recruitment statements. Neither a current vacancy nor current absence of vacancies is established.</p>':''}${c.qualifiers?.assertion_scope==='company_advertised_service_and_performance_promise'?'<p class="audit-meta">Company-advertised services and performance promise. Independent performance evidence or a contractual guarantee is not established.</p>':''}${c.qualifiers?.source_scope==='independently_declared_website_relationship'?'<p class="audit-meta">Website declared by the independently identified company pressroom. Destination content was not collected or verified.</p>':''}${c.qualifiers?.source_scope==='entity_declared_service_catalogue'?'<p class="audit-meta">Advertised services attached to this exact business. Independent approval and completion of projects are not established.</p>':''}${c.qualifiers?.source_scope==='network_published_business_representation'?'<p class="audit-meta">Exact business representation published by its network. Host ownership and administrative account control are not established.</p>':''}${c.qualifiers?.source_scope==='partner_subject'?'<p class="audit-meta">Target-specific services reported on a partner’s page. Host ownership and current certification are not independently established.</p>':''}${c.qualifiers?.source_scope==='entity_page'?'<p class="audit-meta">Entity-specific page on a shared or brand host; parent and other-entity facts are outside this claim.</p>':''}${locationScopeView(c)}${c.qualifiers?.email_obfuscated?'<p class="audit-meta">The preserved text masks the email address. The placeholder is not a usable contact address.</p>':''}${c.qualifiers?.retrieval_date_is_duration_reference===false?'<p class="audit-meta">Relative duration is reported by the source; its reference date is unconfirmed. Retrieval does not restart the stated period.</p>':''}${c.qualifiers?.current_independent_provider_established===false?`<p class="audit-meta">${text(c.qualifiers.migration_context??'Product information reported during a provider transition; current independent operation by this legal company is not established.')}</p>`:''}${c.qualifiers?.postcode_omitted_due_to_unresolved_source_conflict?`<p class="audit-meta">Postcode omitted: the source reports ${text(c.qualifiers.source_postcode)}, while the registry reports ${text(c.qualifiers.registry_postcode)}. The discrepancy remains unresolved.</p>`:''}${c.reporting_period?`<p class="audit-meta">${text(({event_date:'Event date',publication_date:'Publication date',scheduled_event_date:'Scheduled event date',survey_year:'Survey year',application_deadline:'Application deadline',project_period_start:'Project period starts',project_period_end:'Project period ends',approval_period_start:'Approval starts',approval_period_end:'Approval ends',fee_validity_year:'Fee validity year',source_date_unclassified:'Source date; role unresolved'})[c.qualifiers?.date_type]??'Source date; role unresolved')} · ${text(c.reporting_period)}${c.qualifiers?.date_precision==='year'?' (year only)':c.qualifiers?.date_precision==='month'?' (month only)':''}</p>`:''}${c.qualifiers?.document_subject_only?`<p class="audit-meta">Historical document observation${c.qualifiers.document_reporting_year?' · report '+text(c.qualifiers.document_reporting_year):''} · page ${text(c.qualifiers.document_page)}. Current status is not established.</p>`:''}${c.qualifiers?.hiring_kind?`<p class="audit-meta">${text(({conflicting_recruitment_statements:'Source recruitment statements conflict; current status unknown',source_scoped_no_listings:'No listings shown in this source; company-wide absence unproven',current_listings_at_observation:'Listings shown when this source was observed',active_vacancy_at_observation:'Active vacancy when this source was observed',explicit_no_open_roles:'Explicitly reports no open roles',self_reported_fully_staffed:'Company reports being fully staffed; current vacancy count not established',dated_vacancy:'Vacancy with a stated application deadline',undated_vacancy:'Undated advertised role; current open status unknown',historical_undated_vacancy:'Historical undated recruitment record; no current opening established',open_application:'Open-application policy',careers_or_vacancy_information:'Recruitment information; active vacancy count not established',source_scoped_active_ads:'Active ads in the checked NAV feed',source_scoped_no_attributed_ads:'No exact-employer ads attributed in the checked NAV feed',historical_expired_vacancy:'Historical expired vacancy; no current opening established',historical_careers_or_vacancy_information:'Historical recruitment information; no current opening established',historical_dated_vacancy:'Historical dated recruitment record; no current opening established'})[c.qualifiers.hiring_kind]??c.qualifiers.hiring_kind)} · observed ${date(c.qualifiers.observed_at)}</p>`:''}${c.qualifiers?.attribution==='exact-org-directory-profile'?'<p class="audit-meta">Directory account link checked against exact organisation number, legal name and registered street/location.</p>':''}${c.evidence_ids.length?`<button class="evidence-link" data-evidence="${text(c.evidence_ids[0])}">◈ &nbsp; Inspect ${c.evidence_ids.length} evidence reference${c.evidence_ids.length===1?'':'s'} →</button>`:''}</article>`).join('');}
function financialView(p){const records=p.claims.find(c=>c.field==='financials')?.value?.records??[];if(!records.length)return '<div class="empty"><h2>No normalized statements available</h2><p>The source did not return usable annual-account data for this company. Missing financial values have not been filled with zero.</p></div>';const scopes=[...new Set(records.map(r=>r.scope))];if(!scopes.includes(state.scope))state.scope=scopes[0];const scoped=records.filter(r=>r.scope===state.scope),record=scoped.find(r=>r.record_id===state.recordId)??scoped[0];state.recordId=record.record_id;const years=p.claims.find(c=>c.field==='financial_history')?.value?.documents??[];return `<div class="section-heading"><div><h3>Annual financial records</h3><p>As filed with Brønnøysundregistrene</p></div><span class="badge">${records.length} records</span></div><div class="financial-controls"><label for="scopeSelect">Scope</label><select class="filter-select" id="scopeSelect">${scopes.map(scope=>`<option value="${text(scope)}" ${state.scope===scope?'selected':''}>${scope==='company'?'Company · legal entity':scope==='group'?'Group · consolidated':'Unspecified scope'}</option>`).join('')}</select><label for="periodSelect">Period</label><select class="filter-select" id="periodSelect">${scoped.map(r=>`<option value="${text(r.record_id)}" ${state.recordId===r.record_id?'selected':''}>${r.comparative_in_later_filing?'Comparative '+text(r.reporting_year??'')+' · full dates not established':text(r.period.start)+' → '+text(r.period.end)}</option>`).join('')}</select></div>${record.source_basis==='visually_reviewed_original_filing'?'<div class="banner info">Selected financial tables were transcribed after visual inspection of original filing pages. This does not establish complete document interpretation or all older filing amounts.'+(record.account_type==='VPFO'?' This is a securities fund: portfolio and management results are separately named; ordinary corporate revenue and operating profit do not apply.':'')+'</div>':''}${record.liquidation_accounts?'<div class="banner info">Liquidation accounts as filed; these are not ordinary going-concern annual accounts.</div>':''}<div class="financial-grid">${Object.entries(record.metrics).map(([field,metric])=>`<div class="financial-stat"><span>${text(fieldLabel(field))}</span><strong class="${metric.amount<0?'negative':''}">${metric.amount===null?'—':text(money(metric.amount,record.currency))}</strong><small>${metric.amount===null?(record.account_type==='VPFO'&&['revenue','operating_result'].includes(field)?'Not applicable to this fund statement':'Not reported in this statement'):text(record.period.end??('Comparative '+record.reporting_year))+' · '+text(record.scope)+' statement'}</small>${metric.evidence_id?`<button class="evidence-link" data-evidence="${text(metric.evidence_id)}">Inspect page evidence →</button>`:''}</div>`).join('')}</div><button class="evidence-link" data-evidence="${text(record.evidence_id??record.evidence_ids?.[0])}">◈ &nbsp; Inspect the original financial record →</button><p class="financial-explainer">Values retain their reported currency and units. No currency conversion or gap filling is performed. A group statement does not replace the individual company statement.</p><div class="record-note ${record.balance_check.status==='mismatch'?'warn':''}">${record.balance_check.status==='balanced'?'✓ Assets match reported equity plus liabilities.':record.balance_check.status==='mismatch'?'△ The source does not balance: assets differ from equity plus liabilities by '+money(record.balance_check.difference,record.currency)+'. Original amounts are preserved.':'Balance cross-check: insufficient reported components.'}</div>${record.warnings.length?`<div class="banner info">${record.warnings.map(text).join('<br>')}</div>`:''}<h3>Available annual-report documents</h3><p class="financial-explainer">These links show available reports. Listing a document does not mean its contents were extracted.</p><div class="financial-controls">${years.length?years.map(doc=>`<a class="secondary" href="${text(doc.url)}" target="_blank" rel="noreferrer">${text(doc.year)} PDF ↗</a>`).join(''):'<span class="muted">No document history returned.</span>'}</div>`;}
function evidenceView(p){const evidence=state.evidenceId?[...p.evidence.filter(e=>e.id===state.evidenceId),...p.evidence.filter(e=>e.id!==state.evidenceId)]:p.evidence;return `<div class="section-heading"><div><h3>Preserved source evidence</h3><p>Exact excerpts used to support published values</p></div><span class="badge">${p.evidence.length} references</span></div>${evidence.map(e=>`<article class="claim-card" id="evidence-${text(e.id)}"><div class="claim-top"><strong>${e.extraction_method==='nav-feed-index-query/v1'?'Derived NAV source query':e.source_class==='public_registry'?'Official registry':e.source_class==='fixture'?'Fictional demo source':e.source_class==='company_owned'?'Attributed company page':'Public web source'}</strong><span class="badge">${date(e.retrieved_at)}</span></div>${/^https:\/\//.test(e.source_url)?`<a class="source-url" href="${text(e.source_url)}" target="_blank" rel="noreferrer">${text(e.source_url)} ↗</a>`:'<span class="source-url">Frozen registry bulk snapshot</span>'}<blockquote class="evidence-quote">${text(e.claim_span)}</blockquote><details><summary class="audit-meta">Audit details · source hash and retrieval time</summary><div class="audit-meta">Retrieved ${text(e.retrieved_at)}<br>SHA-256: ${text(e.content_sha256)}<br>Method: ${text(e.extraction_method??'Recorded extraction')}<br>Snapshot: ${text(e.snapshot_id)}</div></details>${state.detail.job.review_only?'<p class="audit-meta">Full source was checked in the benchmark audit; its raw cache is not included in this portable review.</p>':`<button class="source-load" data-snapshot="${text(e.snapshot_id)}" data-target="source-${text(e.id)}">Load saved source & verify hash →</button>`}<div id="source-${text(e.id)}"></div></article>`).join('')||'<div class="empty">No source evidence was saved.</div>'}`;}
function changesView(p){return (p.claim_history?.length?`<details class="claim-card"><summary>Claim history · freshness and processing revisions</summary>${p.claim_history.map(c=>`<p><strong>${text(fieldLabel(c.field))}</strong> · ${text(c.kind)} · ${text(c.freshness)}<br>${c.freshness==='withdrawn'?'Prior publication withdrawn':'Last supported'} ${text(c.last_observed)}${c.withdrawal_reason?'<br>'+text(c.withdrawal_reason):''}${c.historical_review_required?'<br>Historical acceptance used an earlier policy; this claim requires re-verification.':c.freshness==='stale'?'<br>Retained historical claim; current run did not re-establish it.':''}</p>`).join('')}</details>`:'')+`<div class="section-heading"><div><h3>Material changes</h3><p>Supported values compared with the last known supported profile</p></div></div>${p.changes.length?p.changes.map(c=>`<article class="claim-card"><h3>${text(fieldLabel(c.field))}</h3><p class="muted">Previous supported value</p><div class="claim-value">${valueView(c.previous_value)}</div><p class="muted">Current supported value</p><div class="claim-value">${valueView(c.current_value)}</div><button class="evidence-link" data-evidence="${text(c.current_evidence_ids[0])}">Inspect current evidence →</button></article>`).join(''):'<div class="empty"><h2>No material changes recorded</h2><p>This may be the first profile, or the supported values are unchanged. Failed sources do not imply that a business fact disappeared.</p></div>'}`;}
function errorsView(p,calls){return `<div class="section-heading"><div><h3>Issues and source requests</h3><p>Partial results stay visible when a source fails</p></div></div>${p.errors.length?p.errors.map(error=>`<div class="error-line"><code>${text(error.code)}</code><span>${text(error.message)}</span></div>`).join(''):'<div class="banner info">No processing issues were recorded. Unresolved fields still appear in the profile.</div>'}<h3 style="margin-top:24px">Source request ledger</h3><div class="table-wrapper"><table><thead><tr><th>Type</th><th>Outcome</th><th>${state.data?.run?.report?.keyless?'External API charge':'Exa charge / reservation'}</th></tr></thead><tbody>${calls.map(call=>`<tr><td>${text(call.kind)}</td><td>${badge(call.state)}</td><td>${!state.data?.run?.report?.keyless&&p.operations.exa_billing&&['search','contents'].includes(call.kind)?'Not reported':usd(call.cost)}</td></tr>`).join('')}</tbody></table></div>`;}
function newRun(){const keyless=Boolean(state.config?.keyless);$('#runMode option[value="eve"]').textContent=keyless?'Live · public sources + Codex':'Live · registry + Exa + eve';$('#runBudget').closest('div').hidden=keyless;$('#modeDescription').textContent=keyless?'Uses public sources and the existing Codex subscription. Model and search API equivalents are recorded separately.':"Uses your configured model and Exa account. The budget applies to this run.";const name='research-'+new Date().toISOString().slice(0,16).replace(/[:T]/g,'-');$('#runName').value=name;$('#formError').hidden=true;$('#newRunDialog').showModal();$('#organisations').focus();}
async function loadSource(button){const target=document.getElementById(button.dataset.target);button.disabled=true;button.textContent='Checking preserved source…';try{const source=await api(`/api/sources/${state.detail.job.id}/${button.dataset.snapshot}`);target.innerHTML=`<p class="record-note ${source.hash_verified?'':'warn'}">${source.hash_verified?'✓ SHA-256 matches the preserved source.':'△ Hash mismatch — inspect this source before relying on it.'}</p>${source.document?`<p class="audit-meta">PDF page ${text(source.document.page_number)} / ${text(source.document.page_count)} · raw SHA-256 ${text(source.document.raw_sha256)} · parser ${text(source.document.parser.id)} ${text(source.document.parser.version)}</p>`:''}<pre class="source-content">${text(source.text)}</pre>`;button.textContent='Saved source loaded';}catch(error){target.innerHTML=`<div class="banner error">${text(error.message)}</div>`;button.disabled=false;button.textContent='Retry loading source';}}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.close){document.getElementById(button.dataset.close).close();return;}if(button.dataset.page){state.page=button.dataset.page;state.tablePage=0;render();return;}if(button.dataset.company){openCompany(button.dataset.company);return;}if(button.dataset.companyTab){state.companyTab=button.dataset.companyTab;renderCompany();return;}if(button.dataset.evidence){state.companyTab='evidence';state.evidenceId=button.dataset.evidence;renderCompany();$('#companyDialog').scrollTop=0;return;}if(button.dataset.snapshot){loadSource(button);return;}if(button.dataset.action==='compare'){compareCompanies();return;}if(button.dataset.action==='prev-page'){state.tablePage--;render();}if(button.dataset.action==='next-page'){state.tablePage++;render();}if(button.dataset.action==='new-run'||button.id==='newRun')newRun();if(button.id==='helpButton')$('#helpDialog').showModal();});
document.addEventListener('input',event=>{if(event.target.id==='companySearch'){state.query=event.target.value;state.tablePage=0;render();}});
document.addEventListener('change',event=>{const id=event.target.id;if(event.target.dataset.compare){const org=event.target.dataset.compare;if(event.target.checked&&state.compare.length>=3){event.target.checked=false;notify('Compare up to three companies at a time.');return;}state.compare=event.target.checked?[...state.compare,org]:state.compare.filter(n=>n!==org);render();return;}if(id==='compareScope'){state.compareScope=event.target.value;renderCompare();return;}if(id==='runSelect'){state.userSelectedRun=true;state.run=event.target.value;state.compare=[];state.tablePage=0;state.query='';state.signature=null;refresh(true);}if(id==='coverageFilter'){state.coverageField=event.target.value;state.tablePage=0;render();}if(id==='statusFilter'){state.status=event.target.value;state.tablePage=0;render();}if(id==='sortCompanies'){state.sort=event.target.value;render();}if(id==='scopeSelect'){state.scope=event.target.value;state.recordId=null;renderCompany();}if(id==='periodSelect'){state.recordId=event.target.value;renderCompany();}if(id==='runMode')$('#modeDescription').textContent=event.target.value==='demo'?'Fictional company evidence. Runs offline with no API calls.':event.target.value==='registry'?'Queries public registry sources. No Exa or model calls.':state.config?.keyless?'Uses public sources and the existing Codex subscription. Model and search API equivalents are recorded separately.':'Uses your configured model and Exa account. The budget applies to this run.';});
$('#runForm').addEventListener('submit',async event=>{event.preventDefault();const organisations=$('#organisations').value.split(/[\s,;]+/).filter(Boolean);$('#formError').hidden=true;if(!organisations.length||organisations.some(org=>!/^\d{9}$/.test(org))){$('#formError').textContent='Enter nine-digit Norwegian organisation numbers.';$('#formError').hidden=false;return;}const button=$('#startRun');button.disabled=true;button.textContent='Starting…';try{const result=await api('/api/runs',{method:'POST',headers:{'content-type':'application/json','x-signalpost-token':state.config.token},body:JSON.stringify({organisations,mode:$('#runMode').value,workers:2,budget_usd:Number($('#runBudget').value),run_id:$('#runName').value})});$('#newRunDialog').close();state.run=result.run_id;state.page='overview';state.signature=null;state.query='';state.tablePage=0;await refresh(true);notify('Research run started. Progress will appear here.');}catch(error){$('#formError').textContent=error.message;$('#formError').hidden=false;}finally{button.disabled=false;button.textContent='Start research →';}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
(async()=>{try{state.config=await api('/api/config');}catch{}await refresh();setInterval(()=>{if(!document.hidden)refresh();},2000);})();

async function compareCompanies(){
  if(state.compare.length<2)return;state.userSelectedRun=true;
  $('#companyPanel').innerHTML='<div class="loading"><span class="spinner"></span> Preparing company comparison…</div>';
  if(!$('#companyDialog').open)$('#companyDialog').showModal();
  try{state.compareProfiles=await Promise.all(state.compare.map(org=>api(`/api/runs/${encodeURIComponent(state.run)}/companies/${org}`)));renderCompare();}catch(error){notify(error.message);$('#companyDialog').close();}
}
function renderCompare(){
  const profiles=state.compareProfiles.map(d=>d.profile).filter(Boolean);
  const selected=profiles.map(p=>{const records=p.claims.find(c=>c.field==='financials')?.value?.records??[];return records.find(r=>r.scope===state.compareScope)??null;});
  $('#companyPanel').innerHTML=`<div class="company-header"><div class="company-header-top"><div><div class="eyebrow">SIDE BY SIDE</div><h2 id="companyTitle">Compare companies</h2><div class="company-meta">Reported amounts, with currency and period kept explicit.</div></div><button class="icon-button" data-close="companyDialog" aria-label="Close comparison">×</button></div></div><div class="company-body"><div class="financial-controls"><label for="compareScope">Statement scope</label><select id="compareScope" class="filter-select"><option value="company" ${state.compareScope==='company'?'selected':''}>Company · legal entity</option><option value="group" ${state.compareScope==='group'?'selected':''}>Group · consolidated</option></select></div><div class="banner info">Amounts in different currencies or reporting periods are not directly comparable. No conversions or inferred values are applied.</div><div class="table-wrapper"><table class="statement-table"><thead><tr><th>Field</th>${profiles.map(p=>`<th>${text(p.claims.find(c=>c.field==='legal_name')?.value??p.organisation_number)}<br><span class="muted">${text(p.organisation_number)}</span></th>`).join('')}</tr></thead><tbody><tr><td>Reporting period</td>${selected.map(r=>`<td>${r?text(r.period.start)+'<br>'+text(r.period.end):'Not reported'}</td>`).join('')}</tr><tr><td>Currency</td>${selected.map(r=>`<td>${text(r?.currency??'Not reported')}</td>`).join('')}</tr>${['revenue','operating_result','annual_result','assets','equity','liabilities'].map(field=>`<tr><td>${text(fieldLabel(field))}</td>${selected.map(r=>`<td>${r&&r.metrics[field]?.amount!==null?text(money(r.metrics[field]?.amount,r.currency)):'Not reported'}</td>`).join('')}</tr>`).join('')}<tr><td>Inspect</td>${profiles.map(p=>`<td><button class="evidence-link" data-company="${text(p.organisation_number)}">Company & evidence →</button></td>`).join('')}</tr></tbody></table></div></div>`;
}
